# -- ported from 0061_set_fismec_invoice_format.py --
def set_fismec_format(apps, schema_editor):
    Company = apps.get_model("company", "Company")
    Company.objects.filter(name="FISMEC").update(
        invoice_number_format="IN-{year}-{number}"
    )


def reverse_fismec_format(apps, schema_editor):
    Company = apps.get_model("company", "Company")
    Company.objects.filter(name="FISMEC").update(
        invoice_number_format="INV-{year}-{number}"
    )


# -- ported from 0069_workingzone_location_confirmed_at.py --
def confirm_existing_zones(apps, schema_editor):
    """
    Zones that already existed before this migration are already in
    production use with proven-good pins, so they should not be treated
    as "unconfirmed" (which would grant them the 2km first-transaction
    leniency and risk relocating an already-correct pin). Only zones
    created after this migration start out unconfirmed.
    """
    WorkingZone = apps.get_model("company", "WorkingZone")
    WorkingZone.objects.filter(location_confirmed_at__isnull=True).update(location_confirmed_at=timezone.now())


